 using Workflow=StateBrowseWorkflowTask;using Numeric=StateProgramBrowseTask;using Bank=StateBankNavigationTask;using Index=StateProgramTask;using Combine=StatePartSelectionTask;using Timer=ScheduledTimerTask;using Clock=ControllerClockReadTask;using Expand=StateParameterExpandTask;using Semitone=StatePanelModesTask;using Mark=PeriodicTask;
 using Task=std::variant<Workflow,Numeric,Bank,Index,Combine,Timer,Clock,Expand,Semitone,Mark>;
 struct Frame {Task task;Node node;Kind kind;Input input;unsigned outcome=0;uint16_t presentation=0,number=0;uint32_t source=0,target=0;bool tail=false,transient=false;uint16_t retainedPresentation=0;};
 static unsigned byteClock(uint32_t raw,int previous){const auto a=raw&0xffffff;if(a<0x400000)return !(previous&1)&&a==(uint32_t(previous)|1u)?0:3;if(a>=0xfffd10&&a<0xffffa0)return !(previous&1)&&a==(uint32_t(previous)|1u)?0:1;return a>=0xffffa0?1:3;}
 static unsigned workflowBus(const Workflow&t,int p){using S=Workflow::Stage;switch(t.stage()){case S::WriteRepeatDelta:return byteClock(0x167f6,p);case S::WriteOpenedFlag:case S::WriteClosedFlag:return byteClock(0x16782,p);case S::ReadSavedProgram:case S::ReadRestoreProgram:return 6;case S::ReadSavedByte:case S::ReadRestoreByte:return byteClock(t.source(),-1);case S::WriteSavedByte:case S::WriteRestoreByte:return byteClock(t.destination(),p);default:return 3;}}
 static unsigned numericBus(const Numeric&t,int p){using S=Numeric::Stage;switch(t.stage()){case S::WriteProgramNumber:return byteClock(0x167ad,p);case S::WriteProgramBank:return byteClock(0x167ac,p);case S::WriteDigitsValue:case S::WriteProgramDigits:return byteClock(0x167fb,p);case S::WriteProgramFirst:return byteClock(0x167f8,p);case S::WriteProgramSecondBlank:case S::WriteProgramSecond:return byteClock(0x167f9,p);case S::WriteProgramThirdBlank:return byteClock(0x167fa,p);default:return 3;}}
 static unsigned bankBus(const Bank&t,int p){using S=Bank::Stage;switch(t.stage()){case S::WriteBankNumber:case S::WriteEnteredNumber:return byteClock(0x167ab,p);case S::WriteEnteredBank:return byteClock(0x167aa,p);case S::WriteDigitLatch:return byteClock(0x167fb,p);case S::WriteFirstDigit:return byteClock(0x167f8,p);case S::WriteSecondBlank:case S::WriteSecondDigit:return byteClock(0x167f9,p);case S::WriteThirdBlank:return byteClock(0x167fa,p);default:return 3;}}
 void edge(Request q,unsigned n){if(!depth_)return;auto&o=*summary_.calls[frames_[depth_-1]->outcome];if(o.count==o.children.size())throw std::logic_error("Browser semantic child capacity");o.children[o.count++]={q,n};}
 template<class T>void start(T task,Node node,Kind kind,Input in,bool transient=false){if(depth_==frames_.size())throw std::logic_error("Browser continuation capacity");unsigned n;if(transient){auto&parent=*frames_[depth_-1];if(parentTransient_==~0u){if(summary_.count==summary_.calls.size())throw std::logic_error("Browser outcome capacity");parentTransient_=summary_.count++;}n=parentTransient_;}else{if(summary_.count==summary_.calls.size())throw std::logic_error("Browser outcome capacity");n=summary_.count++;edge(Request::None,n);}summary_.calls[n].emplace(Outcome{node,kind,in});auto&o=*summary_.calls[n];o.facts.presentation=depth_?frames_[depth_-1]->presentation:in.event;o.facts.value=in.value;o.facts.limit=in.limit;frames_[depth_++].emplace(Frame{Task{std::move(task)},node,kind,in,n,o.facts.presentation,in.value,0,0,false,transient});components_|=1u<<unsigned(node);}
